// settings.ts -- the application settings, assembled once at startup
//
// Auto-generated by cruftfree-codegen-typescript. Do not edit manually.
//
// Assembled from the deployment-static bootstrap constants, the config store's
// `connections` namespace and the deploy-time application settings the
// platform delivers. Credentials are NOT copied here: whatever can rotate is resolved
// through `SecretsService` at the point of use.
//
// The only environment reads in the service are the deploy-time application settings
// in this module (`requireDeployTimeSetting`): values the platform deployment delivers
// as application settings (ARM outputs, for instance), static for the deployment's
// lifetime and read once. Every other fact is baked, read from the config store, or
// resolved through the secrets service -- never the environment.
//
// `assembleSettings()` is awaited by `main.ts` before the application module is
// built; a reader requested before that throws instead of seeing no settings. The
// exceptions are `deployTimeSettingAtBoot` and `optionalSettingAtBoot`, the telemetry
// bootstrap's reads of a deploy-time setting before anything else loads.

// A type-only import: the client module (and the config-store SDK it loads) is loaded
// when the assembly runs, so the tracing bootstrap can import this module before any
// instrumented module loads.
import type { RemoteConfigClient } from './remoteConfig';
import { Global, Module } from '@nestjs/common';
import { PROFILE } from './_bootstrap';

const CONNECTIONS_NAMESPACE = "connections";

/** The non-secret connection facts, read from the config store's `connections` namespace. */
export interface ConnectionSettings {
  readonly email_db_database: string;
  readonly email_db_host: string;
  readonly email_db_port: number;
  readonly email_db_user: string;
  readonly tracing_connection_string: string;
}

/** The deploy-time application settings the service requires. */
export const REQUIRED_DEPLOY_TIME_SETTINGS = [
  "CRUFTFREE_CALLER_AUDIENCE_CLIENT_ID",
  "CRUFTFREE_CALLER_EXPECTED_ISSUER",
  "CRUFTFREE_CALLER_TRUSTED_PRINCIPAL_IDS",
] as const;

/** The deploy-time application settings the platform may leave unset on some hosts. */
export const OPTIONAL_DEPLOY_TIME_SETTINGS = [
  "APPLICATIONINSIGHTS_CONNECTION_STRING",
  "CRUFTFREE_DB_USERNAME",
] as const;

export type RequiredDeployTimeSetting = (typeof REQUIRED_DEPLOY_TIME_SETTINGS)[number];
export type OptionalDeployTimeSetting = (typeof OPTIONAL_DEPLOY_TIME_SETTINGS)[number];

/** The frozen application settings of the running service. */
export interface AppSettings {
  /** The deployment profile this service was generated for. */
  readonly profile: string;
  readonly connections: Readonly<ConnectionSettings>;
  readonly deployTime: Readonly<Record<RequiredDeployTimeSetting, string>>;
  readonly optionalDeployTime: Readonly<Record<OptionalDeployTimeSetting, string | null>>;
}

/** Injection token of the assembled {@link AppSettings}. */
export const APP_SETTINGS = Symbol('APP_SETTINGS');

/**
 * A deploy-time application setting the platform delivers. Fails loud when it is unset
 * or blank: a missing value is a deployment wiring bug, never a valid "disabled" state.
 */
function requireDeployTimeSetting(name: string): string {
  const value = (process.env[name] ?? '').trim();
  if (value === '') {
    throw new Error(
      `Required app setting '${name}' is missing or empty. This value is delivered as an ` +
        'application setting by the platform deployment. Verify the deployment wired this ' +
        'app setting before startup.',
    );
  }
  return value;
}

/** A deploy-time application setting that a host may legitimately leave unset. */
function optionalDeployTimeSetting(name: string): string | null {
  const value = (process.env[name] ?? '').trim();
  return value === '' ? null : value;
}

let assembled: AppSettings | null = null;
let assembling: Promise<AppSettings> | null = null;

/**
 * Assemble the settings once and return them.
 *
 * Fails loud when a required config-store key or deploy-time application setting is
 * absent. Idempotent: every caller awaits the same assembly.
 */
export function assembleSettings(): Promise<AppSettings> {
  assembling ??= assembleOnce();
  return assembling;
}

async function assembleOnce(): Promise<AppSettings> {
  const { sharedConfigClient } = await import('./remoteConfig');
  const config: RemoteConfigClient = sharedConfigClient();
  await config.start();
  const connections: ConnectionSettings = {
    email_db_database: config.getString(CONNECTIONS_NAMESPACE, "email_db_database"),
    email_db_host: config.getString(CONNECTIONS_NAMESPACE, "email_db_host"),
    email_db_port: config.getInt(CONNECTIONS_NAMESPACE, "email_db_port"),
    email_db_user: config.getString(CONNECTIONS_NAMESPACE, "email_db_user"),
    tracing_connection_string: config.getString(CONNECTIONS_NAMESPACE, "tracing_connection_string"),
  };
  const deployTime = {
    "CRUFTFREE_CALLER_AUDIENCE_CLIENT_ID": requireDeployTimeSetting("CRUFTFREE_CALLER_AUDIENCE_CLIENT_ID"),
    "CRUFTFREE_CALLER_EXPECTED_ISSUER": requireDeployTimeSetting("CRUFTFREE_CALLER_EXPECTED_ISSUER"),
    "CRUFTFREE_CALLER_TRUSTED_PRINCIPAL_IDS": requireDeployTimeSetting("CRUFTFREE_CALLER_TRUSTED_PRINCIPAL_IDS"),
  } as Record<RequiredDeployTimeSetting, string>;
  const optionalDeployTime = {
    "APPLICATIONINSIGHTS_CONNECTION_STRING": optionalDeployTimeSetting("APPLICATIONINSIGHTS_CONNECTION_STRING"),
    "CRUFTFREE_DB_USERNAME": optionalDeployTimeSetting("CRUFTFREE_DB_USERNAME"),
  } as Record<OptionalDeployTimeSetting, string | null>;
  assembled = Object.freeze({
    profile: PROFILE,
    connections: Object.freeze(connections),
    deployTime: Object.freeze(deployTime),
    optionalDeployTime: Object.freeze(optionalDeployTime),
  });
  console.info(`app_settings_assembled environment=${PROFILE}`);
  return assembled;
}

/** The assembled settings. Throws when called before {@link assembleSettings} has completed. */
export function getSettings(): AppSettings {
  if (assembled === null) {
    throw new Error(
      'The application settings have not been assembled yet. Await assembleSettings() ' +
        'during bootstrap (main.ts does, before the application module is built) before ' +
        'reading any setting.',
    );
  }
  return assembled;
}

/** The value of a required deploy-time application setting, from the assembled settings. */
export function deployTimeSetting(name: RequiredDeployTimeSetting): string {
  return getSettings().deployTime[name];
}

/** The value of an optional deploy-time application setting, or `null` when the host left it unset. */
export function optionalSetting(name: OptionalDeployTimeSetting): string | null {
  return getSettings().optionalDeployTime[name];
}

/**
 * The value of a required deploy-time application setting, read before the assembly: for the
 * telemetry bootstrap, which must start before any instrumented module loads and so before
 * {@link assembleSettings} can run. The same read the assembly makes; throws when unset or blank.
 */
export function deployTimeSettingAtBoot(name: RequiredDeployTimeSetting): string {
  return requireDeployTimeSetting(name);
}
/**
 * The value of an optional deploy-time application setting, read before the assembly: for the
 * telemetry bootstrap, which must start before any instrumented module loads and so before
 * {@link assembleSettings} can run. The same read the assembly makes; `null` when unset or blank.
 */
export function optionalSettingAtBoot(name: OptionalDeployTimeSetting): string | null {
  return optionalDeployTimeSetting(name);
}

/**
 * The value of a deploy-time application setting whose NAME is data, not source: the late-bound
 * audience references of the identity provider plan name the settings the platform delivers
 * (an identity provider assigns the audience when the registration converges), so no call site
 * can spell them. `null` when the host left the setting unset or blank; the caller decides what
 * an unresolved reference means.
 */
export function lateBoundSetting(name: string): string | null {
  const value = (process.env[name] ?? '').trim();
  return value === '' ? null : value;
}

/**
 * Provides {@link AppSettings} under {@link APP_SETTINGS} to every module.
 *
 * The provider is asynchronous, so Nest finishes the assembly before it constructs any
 * provider that injects the settings -- in the web application and in every standalone
 * worker, scheduler and handler context that imports this module. A caller outside
 * dependency injection reads them through {@link getSettings}, which is valid once the
 * context that imports this module has initialised.
 */
@Global()
@Module({
  providers: [{ provide: APP_SETTINGS, useFactory: assembleSettings }],
  exports: [APP_SETTINGS],
})
export class SettingsModule {}
